 */
import sas.*;
import java.awt.Color;
public class WolfUndSchafe
{
   private View view;
   private Spielfeld spielfeld;
   private SpielerSchaf spSchaf;
   private SpielerWolf spWolf;
   private boolean wolfAmZug;
   private Text textMeldung;

    /**
     * Konstruktor für Objekte der Klasse Spiel
     */
   public WolfUndSchafe()
   {
      view = new View(400, 450, "Wolf und Schafe");
      wolfAmZug = true;
      spielfeld = new Spielfeld();
      spSchaf = new SpielerSchaf(spielfeld);
      spWolf = new SpielerWolf(spielfeld);
      textMeldung = new Text(5, 415, "Wolf ist am Zug");
      textMeldung.setFontSansSerif(false, 16);
   }

   public void spielen() {
      int ende = 0;
      while (ende == 0) {
         textMeldung.setText("Wolf ist am Zug");
         spWolf.wolfZug();
         ende = spielfeld.spielBeendet();
         if (ende != 2) {
            textMeldung.setText("Schafe sind am Zug"); 
            spSchaf.schafzug();
            ende = spielfeld.spielBeendet(); 
         }
      }
      if (ende == 2) {
         textMeldung.setText("Wolf hat gewonnen");
      } else {
         textMeldung.setText("Schafe haben gewonnen");
      }
   } 

   public static void main(String[] args) {
      WolfUndSchafe wus = new WolfUndSchafe();
      wus.spielen();
   }
}

/**
 * Beschreiben Sie hier die Klasse spielstein.
 * 
 * @author (Ihr Name) 
 * @version (eine Versionsnummer oder ein Datum)
 */
import sas.*;
import java.awt.Color;
public class Spielstein
{
    private Circle spielstein;
    private SpielPosition pos;
    private Spielfeld spfd;
    /**
     * Konstruktor für Objekte der Klasse spielstein
     */
    public Spielstein(Spielfeld pSpfd, int pXPos, int pYPos, Color farbe)
    {
        spfd = pSpfd;
        spielstein = new Circle(spfd.kachelXInPixelX(pXPos)+3, spfd.kachelYInPixelY(pYPos)+3, 
                 (spfd.gibKachelBreite()-6)/2, farbe);
        pos = new SpielPosition(pXPos, pYPos);
    }

    public void bewegeAuf(SpielPosition pPosition){
      spielstein.moveTo(spfd.kachelXInPixelX(pPosition.gibXPosition())+3, spfd.kachelYInPixelY(pPosition.gibYPosition())+3);
      pos.setzePosition(pPosition.gibXPosition(), pPosition.gibYPosition());
    }

    public SpielPosition bewegeMitMaus(){
      double altX = spielstein.getMouseX();
      double altY = spielstein.getMouseY();
      while (spielstein.mouseDragged()){ 
          double neuX = spielstein.getMouseX();
          double neuY = spielstein.getMouseY();
          spielstein.move(neuX - altX, neuY - altY);
          altX = neuX;
          altY = neuY;
      }
      double cx = spielstein.getCenterX();
      double cy = spielstein.getCenterY();
      return new SpielPosition(spfd.pixelXInKachelX(cx), spfd.pixelYInKachelY(cy));
    }

    public SpielPosition gibPosition() {
        return pos;
    }

}

/**
 * Beschreiben Sie hier die Klasse SpielerSchaf.
 * 
 * @author (Ihr Name) 
 * @version (eine Versionsnummer oder ein Datum)
 */
import sas.Tools;
public class SpielerWolf
{
    Spielfeld spielfeld;
    Spielstein wolf;
    Spielstein[] schafe;
    int zugNummer;

    /**
     * Konstruktor für Objekte der Klasse SpielerSchaf
     */
    public SpielerWolf(Spielfeld pSpielfeld)
    {
        spielfeld = pSpielfeld;
        wolf = pSpielfeld.gibWolf();
        schafe = pSpielfeld.gibSchafe();
        zugNummer = 0;
    }

    /**
     * Ein Beispiel einer Methode - ersetzen Sie diesen Kommentar mit Ihrem eigenen
     * 
     * @param  y    ein Beispielparameter für eine Methode
     * @return        die Summe aus x und y
     */
    public void wolfzug()
    {
        boolean gezogen = false;
        SpielPosition altePosition = new SpielPosition(0,0);
        SpielPosition neuePosition = new SpielPosition(0,0);
        int i = 0; 
        while (!gezogen) {
            while (!gezogen) {   
               altePosition = wolf.gibPosition();
               neuePosition = wolf.bewegeMitMaus();
               if (!altePosition.istGleich(neuePosition)) {
                 gezogen = true;
               } else {
                   spielfeld.zieheNach(wolf,altePosition);
                }
            }
            if (!spielfeld.zugZulaessig(wolf,neuePosition,false)) {
                gezogen = false;
                spielfeld.zieheNach(wolf,altePosition);
            }

        }
        spielfeld.zieheNach(wolf,neuePosition);
    }

    public String sucheMaxWeg(SpielPosition pPos, String pWeg, String pMaxWeg) {
        SpielPosition neuePosition = new SpielPosition(pPos.gibXPosition()+1,pPos.gibYPosition()-1);
        if (!spielfeld.feldBelegt(neuePosition) && spielfeld.imFeld(neuePosition)) {
            pWeg=pWeg+"r";
            pMaxWeg = sucheMaxWeg(neuePosition, pWeg, pMaxWeg);
            pWeg = pWeg.substring(0,pWeg.length()-1);
        } else {
            if (pWeg.length()>pMaxWeg.length()) {
                pMaxWeg = pWeg;
            } 
         }
        neuePosition = new SpielPosition(pPos.gibXPosition()-1,pPos.gibYPosition()-1);
        if (!spielfeld.feldBelegt(neuePosition) && spielfeld.imFeld(neuePosition)) {
            pWeg=pWeg+"l";
            pMaxWeg = sucheMaxWeg(neuePosition, pWeg, pMaxWeg);
        } else {
            if (pWeg.length()>pMaxWeg.length()) {
                pMaxWeg = pWeg;
            }
         } 
         return pMaxWeg;
    }

    public SpielPosition berechneWolfZug() {
       SpielPosition neuePosition;
       int wolfX = wolf.gibPosition().gibXPosition();
       int wolfY = wolf.gibPosition().gibYPosition();
       String maxWeg = "";
       maxWeg = sucheMaxWeg(wolf.gibPosition(),"", maxWeg);
       if (maxWeg.length()>0){
               if (maxWeg.substring(0,1).equals("l")) {
                  neuePosition = new SpielPosition(wolfX-1,wolfY-1); 
               } else {
                   neuePosition = new SpielPosition(wolfX+1,wolfY-1);
                }
       } else { //Wolf muss zurück
            if (wolfX==7) {
               neuePosition = new SpielPosition(wolfX-1,wolfY+1);
            } else if (wolfX==0) {
               neuePosition = new SpielPosition(wolfX+1,wolfY+1); 
            } else {
              //Richtung zufällig bestimmen  
              int richtung = Tools.randomNumber(1,2);
              if (richtung == 1) {
                 neuePosition = new SpielPosition(wolfX+1,wolfY+1);
              } else {
                 neuePosition = new SpielPosition(wolfX-1,wolfY+1);
              }
            }
        }
       return neuePosition;
    }

    public void wolfZug() {
       SpielPosition neuePosition = this.berechneWolfZug();
       spielfeld.zieheNach(wolf,neuePosition);    
    }
}

/**
 * EIn Objekt der KLasse ist der Spieler, der Schafsteine 
 * 
 * @author Klaus Dingemann 
 * @version 29.01.2018
 */
public class SpielerSchaf {
    Spielfeld spielfeld;
    Spielstein[] schafe;

    public SpielerSchaf(Spielfeld pSpielfeld) {
        spielfeld = pSpielfeld;
        schafe = pSpielfeld.gibSchafe();
    }

    public void schafzug() {
        boolean gezogen = false;
        SpielPosition altePosition = new SpielPosition(0,0);
        SpielPosition neuePosition = new SpielPosition(0,0);
        int i = 0; 
        while (!gezogen) {   
           altePosition = schafe[i].gibPosition();
           neuePosition = schafe[i].bewegeMitMaus();
           if (!altePosition.istGleich(neuePosition)) {
             gezogen = true;
           } else {
               spielfeld.zieheNach(schafe[i],altePosition);
               i = (i+1) % 4;
             }
        }
        if (!spielfeld.zugZulaessig(schafe[i],neuePosition,true)) {
          gezogen = false;
          spielfeld.zieheNach(schafe[i],altePosition);
        }   
        spielfeld.zieheNach(schafe[i],neuePosition);
    }
}

/**
 * Ein Objekt dieser klasse ist ein Spielfeld für das Spiel
 * Wolf und Schafe. Das Spielfeld überprüft die Korrektheit 
 * der Züge und überprüft das Spielende.
 * 
 * @author Klaus Dingemann 
 * @version 29.01.2018
 */
import sas.*;
import java.awt.Color;
public class Spielfeld extends Rasterflaeche
{
    Spielstein steinWolf;
    Spielstein[] schafe = new Spielstein[4];


    /**
     * Konstruktor für Objekte der Klasse Spielfeld
     */

    public Spielfeld()
    {
       super(8, 8, 400, 400, Color.WHITE);
       this.schachBrett(Color.BLACK);
       steinWolf = new Spielstein(this, 4, 7, Color.RED);
       schafe[0] = new Spielstein(this, 1, 0, Color.YELLOW);
       schafe[1] = new Spielstein(this, 3, 0, Color.YELLOW);
       schafe[2] = new Spielstein(this, 5, 0, Color.YELLOW);
       schafe[3] = new Spielstein(this, 7, 0, Color.YELLOW);
    }

    public boolean feldBelegt(SpielPosition pPosition) {
      boolean mitSchafBelegt = false;
      for (int i=0; i<4; i++) {
          mitSchafBelegt = mitSchafBelegt || pPosition.istGleich(schafe[i].gibPosition());
      }
      return pPosition.istGleich(steinWolf.gibPosition()) || mitSchafBelegt;
    }

    public boolean imFeld(SpielPosition pPosition) {
        return this.istInnen(pPosition.gibXPosition(), pPosition.gibYPosition());
    }

    public boolean zugZulaessig (Spielstein pSpielstein,SpielPosition pNeuePosition,  boolean pIstSchaf) {
        if (pIstSchaf) {
          int x = pNeuePosition.gibXPosition();
          int y = pNeuePosition.gibYPosition();
          boolean innen = this.istInnen(x, y); 
          boolean zugRegelX = Math.abs(pNeuePosition.gibXPosition()-pSpielstein.gibPosition().gibXPosition())==1; 
          boolean zugRegelY= pNeuePosition.gibYPosition()-pSpielstein.gibPosition().gibYPosition()==1; 
          return innen && zugRegelX && zugRegelY && !feldBelegt(pNeuePosition);
        } else { 
            return  this.istInnen(pNeuePosition.gibXPosition(), pNeuePosition.gibYPosition()) &&
                    Math.abs(pNeuePosition.gibXPosition()-pSpielstein.gibPosition().gibXPosition())==1 &&
                    Math.abs(pNeuePosition.gibYPosition()-pSpielstein.gibPosition().gibYPosition())==1 && 
                    !feldBelegt(pNeuePosition);
        }
    }    

    public void zieheNach (Spielstein pSpielstein,SpielPosition pNeuePosition) {
        pSpielstein.bewegeAuf(pNeuePosition);     
    }

    public Spielstein[] gibSchafe() {
        return schafe;
    }

    public Spielstein gibWolf() {
       return steinWolf;
    }

    public int spielBeendet(){
        int xPosition = steinWolf.gibPosition().gibXPosition();
        int yPosition = steinWolf.gibPosition().gibYPosition();
        boolean zug1zulaessig = zugZulaessig(steinWolf, new SpielPosition(xPosition+1, yPosition+1),false);
        boolean zug2zulaessig = zugZulaessig(steinWolf, new SpielPosition(xPosition+1, yPosition-1),false);
        boolean zug3zulaessig = zugZulaessig(steinWolf, new SpielPosition(xPosition-1, yPosition+1),false);
        boolean zug4zulaessig = zugZulaessig(steinWolf, new SpielPosition(xPosition-1, yPosition-1),false);
        boolean wolfKannNichtZiehen = !(zug1zulaessig || zug2zulaessig || zug3zulaessig || zug3zulaessig);
        int minSchafPosition = schafe[0].gibPosition().gibYPosition();
        for (int i = 1; i<4; i++) {
            if (schafe[i].gibPosition().gibYPosition() < minSchafPosition) {
                minSchafPosition = schafe[i].gibPosition().gibYPosition();
            }
        }
        boolean wolfDurchgebrochen=false;
        if (steinWolf.gibPosition().gibYPosition() <= minSchafPosition) {
            wolfDurchgebrochen = true;
        } else {
            wolfDurchgebrochen = false;
        }
        if (wolfKannNichtZiehen) {
            return 1;
        } else if (wolfDurchgebrochen) {
            return 2;
        } else {
            return 0;
        }
    }
}

/**
 * Beschreiben Sie hier die Klasse Rasterflaeche.
 * 
 * @author (Ihr Name) 
 * @version (eine Versionsnummer oder ein Datum)
 */
import sas.*;
import java.awt.Color;
public class Rasterflaeche
{
    // Instanzvariablen - ersetzen Sie das folgende Beispiel mit Ihren Variablen
    private int anzahlKachelnX;
    private int anzahlKachelnY;
    private int pixelBreite;
    private int pixelHoehe;
    private int kachelBreite;
    private int kachelHoehe;
    private Rectangle hintergrund;
    private Kachel[][] kacheln;
    /**
     * Konstruktor für Objekte der Klasse Rasterflaeche
     */
    public Rasterflaeche(int pAnzahlKachelnX, int pAnzahlKachelnY, double pPixelBreite, double pPixelHoehe, 
           Color pKachelfarbe)
    {
       anzahlKachelnX = pAnzahlKachelnY;
       anzahlKachelnY = pAnzahlKachelnY;
       kachelBreite = (int)pPixelBreite / pAnzahlKachelnX;
       kachelHoehe = (int)pPixelHoehe / pAnzahlKachelnY;
       pixelBreite = kachelBreite * anzahlKachelnX;
       pixelHoehe = kachelHoehe * anzahlKachelnY;
       hintergrund = new Rectangle(0, 0, pixelBreite, pixelHoehe, new Color(200, 200, 200));
       kacheln = new Kachel[anzahlKachelnX][anzahlKachelnY];
       for (int i = 0; i<anzahlKachelnX ;i++) {
           for (int j = 0; j < anzahlKachelnY; j++) {
               kacheln[i][j] = new Kachel(i,j,kachelBreite,kachelHoehe, pKachelfarbe);
            }
        }
    }

    public void schachBrett(Color pFarbe) {
           for (int i = 0; i< anzahlKachelnX ;i++) {
           for (int j = 0; j < anzahlKachelnY; j++) {
               if (i % 2 == 0 && j % 2  == 0 || i % 2 == 1 && j % 2 == 1) {
                   kacheln[i][j].setzeFarbe(pFarbe);
                }
            }
        }
    }

    public int kachelXInPixelX(int pX) {
       return pX*kachelBreite+1;
    }

    public int kachelYInPixelY(int pY) {
       return pY*kachelHoehe+1;
    }

    public int pixelXInKachelX(double pX) {
       return (int)pX / kachelBreite;
    }

    public int pixelYInKachelY(double pY) {
       return (int)pY / kachelHoehe;
    }

    public void setzeHindernis(int pX, int pY, Color pColor) {
        if (pX>=0 && pX < anzahlKachelnX && pY >= 0 && pY < anzahlKachelnY) {
            kacheln[pX][pY].setzteHindernis(pColor);
        }
    }

    public boolean istHindernis(int pX, int pY) {
        return kacheln[pX][pY].istHindernis();
    }

    public boolean istInnen(int pX, int pY) {
        boolean innen =  (pX>=0) && (pX<anzahlKachelnX) && (pY>=0) && (pY<anzahlKachelnY);
        return innen;
    }

    public int gibKachelBreite() {
        return kachelBreite;
    }

    public int gibKachelHoehe(){
        return kachelHoehe;
    }

    public Kachel gibKachel(int pX, int pY) {
        return kacheln[pX][pY];
    }

}

/**
 * Beschreiben Sie hier die Klasse Kachel.
 * 
 * @author (Ihr Name) 
 * @version (eine Versionsnummer oder ein Datum)
 */
import java.awt.Color;
import sas.*;
public class Kachel
{
    // Instanzvariablen - ersetzen Sie das folgende Beispiel mit Ihren Variablen
    private int x;
    private int y;
    private Color farbe;
    private boolean hindernis;
    private Rectangle rechteck;

    /**
     * Konstruktor für Objekte der Klasse Kachel
     */
    public Kachel(int pX, int pY, int pKachelBreite, int pKachelHoehe, Color pFarbe)
    {
        x = pX;
        y = pY;
        farbe = pFarbe;
        hindernis = false;
        rechteck = new Rectangle(pX*pKachelBreite+1, pY*pKachelHoehe+1, pKachelBreite - 2, pKachelHoehe - 2, pFarbe);
    }

    public void setzeFarbe(Color pFarbe) {
        rechteck.setColor(pFarbe);
    }

    public void setzteHindernis(Color pHindernisFarbe) {
      hindernis = true;
      rechteck.setColor(pHindernisFarbe);
    }

    public void entferneHindernis() {
        hindernis = false;
        rechteck.setColor(farbe);
    }

    public boolean istHindernis() {
        return hindernis;
    }

    public int gibX() {
        return x;
    }

    public int gibY() {
        return y;
    }
}

public class SpielPosition
{
    private int xPosition;
    private int yPosition;

    public SpielPosition(int pX, int pY)
    {
        xPosition = pX;
        yPosition = pY;
    }

    public void setzePosition(int pXPos, int pYPos) 
    {
        xPosition = pXPos;
        yPosition = pYPos;
    }

    public int gibXPosition() {
        return xPosition;
    }

    public int gibYPosition() {
        return yPosition;
    }    

    public boolean istGleich(SpielPosition pPos) {
       return pPos.gibXPosition() == this.gibXPosition() &&
              pPos.gibYPosition() == this.gibYPosition();
    }
}
